export function getMultilingualUnitAudioPath(languageId: string, unitId: string): string | null {
  return unitAudio[`${languageId}:${unitId}`] ?? null;
}

export function getMultilingualTextAudioPath(languageId: string, text: string): string | null {
  return textAudio[`${languageId}:${text.trim()}`] ?? null;
}

